create table if not exists case_studies (id serial primary key, slug text unique not null, title text not null, kind text not null, summary text not null, tags text[] not null, links jsonb not null default '{}', "sortOrder" integer not null);
create table if not exists case_study_blocks (id serial primary key, case_study_id integer references case_studies(id) on delete cascade, heading text not null, body text not null, "sortOrder" integer not null);
create unique index if not exists case_study_blocks_unique on case_study_blocks(case_study_id,"sortOrder");
create table if not exists metrics (id serial primary key, value text not null, label text not null unique, basis text, "sortOrder" integer not null);
create table if not exists contact_messages (id serial primary key, name text not null, email text not null, message text not null, created_at timestamptz not null default now(), ip_hash text not null);
create table if not exists analytics_events (id serial primary key, event text not null, slug text, created_at timestamptz not null default now());
delete from case_study_blocks where case_study_id in (select id from case_studies) and (heading,body) in (select kind,summary from case_studies);
